HRESULT WINAPI VarDecFromCy(CY cyIn, DECIMAL* pDecOut)
{
  pDecOut->Hi32 = 0;
  pDecOut->scale = 4;

  if (cyIn.int64 < 0)
  {
      pDecOut->sign = DECIMAL_NEG;
      pDecOut->Lo64 = -cyIn.int64;
  }
  else
  {
      pDecOut->sign = DECIMAL_POS;
      pDecOut->Lo64 = cyIn.int64;
  }
  return S_OK;
}
